.translate_x => |x| {
_ = try dest.writeStr((if (dest.minify) "translate(" else "translateX("));
        _ = try x.toCss(dest);
        _ = try dest.writeChar(41);
},
.translate_y => |y| {
_ = try dest.writeStr("translateY(");
        _ = try y.toCss(dest);
        _ = try dest.writeChar(41);
},
.translate_z => |z| {
_ = try dest.writeStr("translateZ(");
        _ = try z.toCss(dest);
        _ = try dest.writeChar(41);
},
