        } else {
            if ((((dest.minify and t.x.isZero()) and (!t.y.isZero())) and t.z.isZero())) {
                _ = try dest.writeStr("translateY(");
                _ = try t.y.toCss(dest);
            } else {
                if ((((dest.minify and t.x.isZero()) and t.y.isZero()) and (!t.z.isZero()))) {
