        } else {
            if ((((dest.minify and (x != 1.0)) and (y == 1.0)) and (z == 1.0))) {
                _ = try dest.writeStr("scaleX(");
                _ = try css.CSSNumberFns.toCss((&x), dest);
            } else {
                if ((((dest.minify and (x == 1.0)) and (y != 1.0)) and (z == 1.0))) {
