                _ = try dest.writeStr("rotateY(");
                _ = try r.angle.toCssWithUnitlessZero(dest);
            } else {
                if ((((dest.minify and (r.x == 0.0)) and (r.y == 0.0)) and (r.z == 1.0))) {
                    _ = try dest.writeStr("rotate(");
                    _ = try r.angle.toCssWithUnitlessZero(dest);
                } else {
                    _ = try dest.writeStr("rotate3d(");
                    _ = try css.CSSNumberFns.toCss((&r.x), dest);
                    _ = try dest.delim(44, false);
                    _ = try css.CSSNumberFns.toCss((&r.y), dest);
                    _ = try dest.delim(44, false);
                    _ = try css.CSSNumberFns.toCss((&r.z), dest);
                    _ = try dest.delim(44, false);
                    _ = try r.angle.toCssWithUnitlessZero(dest);
                }
            }
        }
        _ = try dest.writeChar(41);
},
.skew => |s| {
if (((dest.minify and s.x.isZero()) and (!s.y.isZero()))) {
            _ = try dest.writeStr("skewY(");
            _ = try s.y.toCssWithUnitlessZero(dest);
        } else {
            _ = try dest.writeStr("skew(");
            _ = try s.x.toCss(dest);
            if ((!s.y.isZero())) {
                _ = try dest.delim(44, false);
                _ = try s.y.toCssWithUnitlessZero(dest);
            }
        }
        _ = try dest.writeChar(41);
},
.skew_x => |angle| {
_ = try dest.writeStr((if (dest.minify) "skew(" else "skewX("));
        _ = try angle.toCssWithUnitlessZero(dest);
        _ = try dest.writeChar(41);
},
.skew_y => |angle| {
_ = try dest.writeStr("skewY(");
        _ = try angle.toCssWithUnitlessZero(dest);
        _ = try dest.writeChar(41);
},
.perspective => |len| {
_ = try dest.writeStr("perspective(");
        _ = try len.toCss(dest);
        _ = try dest.writeChar(41);
},
.matrix => |m| {
_ = try dest.writeStr("matrix(");
        _ = try css.CSSNumberFns.toCss((&m.a), dest);
        _ = try dest.delim(44, false);
        _ = try css.CSSNumberFns.toCss((&m.b), dest);
        _ = try dest.delim(44, false);
        _ = try css.CSSNumberFns.toCss((&m.c), dest);
