pub fn Matrix(comptime T: type) type {
        return struct {
    a: T,
    b: T,
    c: T,
    d: T,
    e: T,
    f: T,

pub fn deepClone(self: @This(), allocator: std.mem.Allocator) @This() {
            return css.implementDeepClone(@This(), (&self), allocator);
    }

pub fn eql(lhs: *const @This(), rhs: *const @This()) bool {
            return css.implementEql(@This(), lhs, rhs);
    }
};
}

pub fn Matrix3d(comptime T: type) type {
        return struct {
    m11: T,
    m12: T,
    m13: T,
    m14: T,
    m21: T,
    m22: T,
    m23: T,
    m24: T,
    m31: T,
    m32: T,
    m33: T,
    m34: T,
    m41: T,
    m42: T,
    m43: T,
    m44: T,

pub fn eql(lhs: *const @This(), rhs: *const @This()) bool {
            return css.implementEql(@This(), lhs, rhs);
    }
};
}

pub fn parseTranslate(input: *css.Parser) css.Result(Translate) {
        if (input.tryParse(css.Parser.expectIdentMatching, .{ "none" }).isOk()) {
            return .{ .result = .none };
        }
        const x = (switch (LengthPercentage.parse(input)) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
});
        const y = input.tryParse(LengthPercentage.parse, .{});
        const z = (if (y.isOk()) input.tryParse(Length.parse, .{}).asValue() else null);
        return .{ .result = Translate{ .xyz = .{ .x = x, .y = y.unwrapOr((comptime LengthPercentage.zero())), .z = ((z) orelse (Length.zero())) } } };
}

pub fn toCssTranslate(this_u: *const Translate, dest: *css.Printer) PrintErr!void {
        switch (this_u.*) {
.none => {
_ = try dest.writeStr("none");
},
.xyz => |xyz| {
_ = try xyz.x.toCss(dest);
        if (((!xyz.y.isZero()) or (!xyz.z.isZero()))) {
            _ = try dest.writeChar(32);
            _ = try xyz.y.toCss(dest);
            if ((!xyz.z.isZero())) {
                _ = try dest.writeChar(32);
                _ = try xyz.z.toCss(dest);
            }
        }
},
}
        return;
}

pub fn toTransformTranslate(this_u: *const Translate, allocator: std.mem.Allocator) Transform {
        return (switch (this_u.*) {
.none => Transform{ .translate_3d = .{ .x = LengthPercentage.zero(), .y = LengthPercentage.zero(), .z = Length.zero() } },
.xyz => |xyz| Transform{ .translate_3d = .{ .x = xyz.x.deepClone(allocator), .y = xyz.y.deepClone(allocator), .z = xyz.z.deepClone(allocator) } },
});
}

pub fn parseScale(input: *css.Parser) css.Result(Scale) {
        if (input.tryParse(css.Parser.expectIdentMatching, .{ "none" }).isOk()) {
            return .{ .result = .none };
        }
        const x = (switch (NumberOrPercentage.parse(input)) {
.result => |v| v,
.err => |e| {
return .{ .err = e };
},
});
        const y = input.tryParse(NumberOrPercentage.parse, .{});
        const z = (if (y.isOk()) input.tryParse(NumberOrPercentage.parse, .{}).asValue() else null);
        return .{ .result = .{ .xyz = .{ .x = x, .y = ((y.asValue()) orelse (x)), .z = ((z) orelse (.{ .number = 1.0 })) } } };
}

pub fn toCssScale(this_u: *const Scale, dest: *css.Printer) PrintErr!void {
        switch (this_u.*) {
.none => {
_ = try dest.writeStr("none");
},
.xyz => |xyz| {
_ = try xyz.x.toCss(dest);
        const z_val = xyz.z.intoF32();
        if (((!xyz.y.eql((&xyz.x))) or (z_val != 1.0))) {
            _ = try dest.writeChar(32);
            _ = try xyz.y.toCss(dest);
            if ((z_val != 1.0)) {
                _ = try dest.writeChar(32);
                _ = try xyz.z.toCss(dest);
            }
        }
},
}
}

pub fn toTransformScale(this_u: *const Scale, allocator: std.mem.Allocator) Transform {
        return (switch (this_u.*) {
.none => Transform{ .scale_3d = .{ .x = .{ .number = 1.0 }, .y = .{ .number = 1.0 }, .z = .{ .number = 1.0 } } },
.xyz => |xyz| Transform{ .scale_3d = .{ .x = xyz.x.deepClone(allocator), .y = xyz.y.deepClone(allocator), .z = xyz.z.deepClone(allocator) } },
});
}
